begin;
set local role postgres;
set local search_path = extensions, public;
select extensions.no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
 ('19000000-0000-4000-8000-000000000001','pgtap-draft-concurrency@example.invalid','{}');
update rush.rush_cycles set status='CLOSED' where status in ('DRAFT','OPEN','IN_PROCESS','DECISION_LOCK');
insert into rush.rush_cycles(id,name,status) values ('pgtap-draft-concurrency','Draft concurrency','OPEN');
create temporary table draft_test_results(key text primary key, value jsonb);
grant all on draft_test_results to authenticated;
set local "request.jwt.claim.sub" = '19000000-0000-4000-8000-000000000001';
set local "request.jwt.claims" = '{"iss":"http://127.0.0.1:54321/auth/v1","sub":"19000000-0000-4000-8000-000000000001","role":"authenticated"}';
set local role authenticated;
select extensions.is(rush.application_draft(),null::jsonb,'an applicant without a row has no draft');
insert into draft_test_results values ('first',rush.save_application_draft_v2('{"name":"First"}',null,'19000000-0000-4000-8000-000000000011','pgtap-draft-concurrency'));
select extensions.is((select value->>'kind' from draft_test_results where key='first'),'saved','first save accepts the absent-row precondition');
select extensions.is(rush.application_draft()->>'revision',(select value->>'revision' from draft_test_results where key='first'),'load returns the actual committed revision');
select extensions.is(rush.save_application_draft_v2('{"name":"First"}',null,'19000000-0000-4000-8000-000000000011','pgtap-draft-concurrency'),(select value from draft_test_results where key='first'),'lost-ack retry returns the same revision');
select extensions.throws_ok($$select rush.save_application_draft_v2('{"name":"Different"}',null,'19000000-0000-4000-8000-000000000011','pgtap-draft-concurrency')$$,'22023','mutation id reused with different draft','a retry id cannot acknowledge different data');
select extensions.is(rush.save_application_draft_v2('{"name":"Stale initial tab"}',null,'19000000-0000-4000-8000-000000000012','pgtap-draft-concurrency')->>'kind','conflict','second initial tab cannot overwrite the first row');
select extensions.is(rush.application_draft()->>'name','First','conflict keeps saved answers intact');
insert into draft_test_results values ('second',rush.save_application_draft_v2('{"name":"Second"}',(select (value->>'revision')::uuid from draft_test_results where key='first'),'19000000-0000-4000-8000-000000000013','pgtap-draft-concurrency'));
select extensions.is((select value->>'kind' from draft_test_results where key='second'),'saved','matching revision can save');
select extensions.isnt((select value->>'revision' from draft_test_results where key='second'),(select value->>'revision' from draft_test_results where key='first'),'a save advances the opaque token');
select extensions.is(rush.save_application_draft_v2('{"name":"Stale tab"}',(select (value->>'revision')::uuid from draft_test_results where key='first'),'19000000-0000-4000-8000-000000000014','pgtap-draft-concurrency')->'draft'->>'name','Second','conflict includes current server answers for explicit recovery');
insert into draft_test_results values ('same-content',rush.save_application_draft_v2('{"name":"Second"}',(select (value->>'revision')::uuid from draft_test_results where key='second'),'19000000-0000-4000-8000-000000000016','pgtap-draft-concurrency'));
select extensions.isnt((select value->>'revision' from draft_test_results where key='same-content'),(select value->>'revision' from draft_test_results where key='second'),'even an unchanged payload advances the revision and cannot leave stale tabs authorized');
select extensions.is(rush.submit_application_v2((select (value->>'revision')::uuid from draft_test_results where key='first'),'pgtap-draft-concurrency','Stale','pgtap-draft-concurrency@example.invalid')->>'kind','conflict','a stale submit is rejected before altering application data');
select extensions.throws_ok($$select rush.save_application_draft('{"name":"Legacy"}')$$,'55000','reload the application to save with a revision','legacy draft writer fails closed');
select extensions.throws_ok($$select rush.save_application_draft_unchecked('{"name":"Bypass"}')$$,'42501','permission denied for function save_application_draft_unchecked','caller cannot bypass draft preconditions');
select extensions.ok(not has_function_privilege('authenticated','rush.submit_application(text,text,text,text,text,text,text,text,jsonb,boolean,text,text,text,text)','EXECUTE'),'legacy submission writer is inaccessible');
select extensions.ok(not has_function_privilege('authenticated','rush.submit_application_reliable(text,text,text,text,text,text,text,text,jsonb,boolean,text,text,text,text)','EXECUTE'),'legacy reliable wrapper cannot bypass preconditions');
set local role postgres;
-- Simulate the committed side of a submission/save interleaving. Real concurrent
-- session scheduling is separate evidence; this suite tests each serialized outcome.
update rush.applications set status='SUBMITTED',submitted_at=now() where cycle_id='pgtap-draft-concurrency';
set local role authenticated;
select extensions.throws_ok($$select rush.save_application_draft_v2('{"name":"Second"}',(select (value->>'revision')::uuid from draft_test_results where key='first'),'19000000-0000-4000-8000-000000000013','pgtap-draft-concurrency')$$,'55000','application can no longer be edited','a delayed draft write cannot resurrect a submitted row');
select extensions.is((rush.submit_application_v2((select (value->>'revision')::uuid from draft_test_results where key='first'),'pgtap-draft-concurrency','Retry','pgtap-draft-concurrency@example.invalid')->>'submittedNow')::boolean,false,'committed submission retry succeeds before comparing its obsolete draft revision');
set local role postgres;
update rush.applications set status='NEEDS_INFO' where cycle_id='pgtap-draft-concurrency';
set local role authenticated;
select extensions.is(rush.save_application_draft_v2('{"name":"Second"}',(select (value->>'revision')::uuid from draft_test_results where key='first'),'19000000-0000-4000-8000-000000000013','pgtap-draft-concurrency')->>'kind','conflict','reopening for more information invalidates old draft receipts');
set local role postgres;
delete from rush.applications where cycle_id='pgtap-draft-concurrency';
set local role authenticated;
select extensions.is(rush.save_application_draft_v2('{"name":"Deleted stale"}',(select (value->>'revision')::uuid from draft_test_results where key='second'),'19000000-0000-4000-8000-000000000015','pgtap-draft-concurrency')->>'kind','conflict','a revision from a deleted row cannot create a replacement');
select extensions.is(rush.application_draft(),null::jsonb,'rejected deleted-row save leaves it absent');
select extensions.finish();
rollback;
